    /// sub_56380 (:61401-08 hw): an active Accelerate burst leaves a
    /// (10,2) contrail — one puff every 4th token f63 tick at the
    /// carpet, owner-stamped, act_life ×4 (ctor 8 → 32). Non-vacuity:
    /// an off-phase tick and a lapsed burst spawn nothing.
    #[test]
    fn accelerate_burst_emits_the_contrail_on_the_4_tick_cadence() {
        let mut w = flat_world();
        // Donor slot repurposed into the owned Accelerate
        // manifestation (native encoding).
        let m = w.g.spawn_effect(3, 0x8000, 0x8000, 3200).expect("slot");
        {
            let e = &mut w.g.ent[m];
            e.class64 = 12;
            e.model65 = 2;
            e.tick70 = MANIFEST_BASE + 2;
            e.f26 = 10; // burst live
            e.f63 = 0; // on-phase
        }
        w.human_pose = (0x8000, 0x8000, 3200);
        let ctx = MobCtx {
            px: 0x8000,
            py: 0x8000,
            pz: 3200,
            pyaw: 0,
            pmana: 0,
            pdead: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let puffs = |w: &World| {
            w.g.ent
                .iter()
                .filter(|e| e.class64 == 10 && e.model65 == 2 && e.flags & 0x400 == 0)
                .count()
        };
        assert_eq!(puffs(&w), 0);
        w.manifestation_tick(m, 2, &ctx);
        assert_eq!(puffs(&w), 1, "on-phase burst tick emits the puff");
        let p =
            w.g.ent
                .iter()
                .position(|e| e.class64 == 10 && e.model65 == 2 && e.flags & 0x400 == 0)
                .unwrap();
        assert_eq!(w.g.ent[p].id24, PLAYER_TARGET, "owner-stamped");
        assert_eq!(w.g.ent[p].act_life, 32, "ctor 8 ×4 (:61407)");
        w.g.ent[m].f63 = 1;
        w.manifestation_tick(m, 2, &ctx);
        assert_eq!(puffs(&w), 1, "off-phase tick spawns nothing");
        w.g.ent[m].f63 = 0;
        w.g.ent[m].f26 = 0; // burst lapsed
        w.manifestation_tick(m, 2, &ctx);
        assert_eq!(puffs(&w), 1, "lapsed burst spawns nothing");
    }

    /// The possess lob's acquisition is ONE-SHOT — the +16&2 latch
    /// (:62952-60): a lob that finds nothing on its first untargeted
    /// tick flies straight forever; a target entering the cone later
    /// must NOT be picked up. (The old per-tick re-acquire was a
    /// misread of the same lines.)
    #[test]
    fn possess_acquisition_is_one_shot() {
        let mut w = flat_world();
        let lob = w.g.spawn_spell_lob(1, 0x8000, 0x8000, 3200).expect("lob");
        {
            let e = &mut w.g.ent[lob];
            e.id24 = 7;
            e.f66 = 10;
            e.f69 = 12;
            e.f30 = 0;
            e.f32 = 0;
        }
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        // Empty cone: the latch arms, no target is found.
        w.g.proj_tick(lob, &ctx);
        assert_eq!(w.g.ent[lob].f146, 0, "nothing to acquire");
        assert_ne!(w.g.ent[lob].flags & 2, 0, "acquire latch armed");

        // A ball dead ahead, well inside cone and range — too late.
        let (lx, ly, lz) = (w.g.ent[lob].x, w.g.ent[lob].y, w.g.ent[lob].z);
        let mut p = (lx, ly, lz);
        Gen::polar_step(&mut p, w.g.ent[lob].f30, 0, 2048);
        let _ball = w.g.spawn_mana_ball(p.0, p.1, 3200).expect("ball");
        w.g.proj_tick(lob, &ctx);
        assert_eq!(
            w.g.ent[lob].f146, 0,
            "latched lob never re-acquires (:62957 sets +16&2 once)"
        );
    }

    /// sub_54A90's selection metric is the 2-D DISTANCE decomposed
    /// onto the angular-error axes (:64212-17) — so a NEAR mana ball
    /// slightly off-axis beats a FAR house sitting dead ahead. The
    /// old pure-angular score (Δyaw²+Δpitch²) chose the house.
    #[test]
    fn possess_acquisition_prefers_the_near_ball_over_the_aligned_far_house() {
        let mut w = flat_world();
        let lob = w.g.spawn_spell_lob(1, 0x8000, 0x8000, 3200).expect("lob");
        // House dead ahead at 4600.
        let house_x = 0x8000u16.wrapping_add(4600);
        let h = w.g.spawn_creator(45, house_x, 0x8000, 3200).expect("house");
        let aim = Gen::angle_between(0x8000, 0x8000, house_x, 0x8000);
        {
            let e = &mut w.g.ent[lob];
            e.id24 = 7;
            e.f66 = 10;
            e.f69 = 12;
            e.f30 = aim;
            e.f32 = 0;
        }
        // Ball at 700, offset 0x50 (~14°) off the aim — inside the
        // ±0x71 cone.
        let mut p = (0x8000u16, 0x8000u16, 3200i16);
        Gen::polar_step(&mut p, (aim + 0x50) & 0x7FF, 0, 700);
        let ball = w.g.spawn_mana_ball(p.0, p.1, 3200).expect("ball");
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        w.g.proj_tick(lob, &ctx);
        assert_eq!(
            w.g.ent[lob].f146, ball as u16,
            "distance-weighted score: the near ball wins over the aligned far house"
        );
        let _ = h;
    }

    /// The full accidental-claim chain, RIVAL-owned end to end: an
    /// untargeted possess lob acquires an unclaimed dwelling (houses
    /// are awake — ctor default +58=0xFA — and live on the possess
    /// acquisition list :64058-71), the impact runs the (10,12) claim
    /// flash, its ch1 broadcast lands on the house, and the live-
    /// building intake re-owns it to the RIVAL tag — retail's
    /// sub_11AC0 (:17061-71) has no player-vs-rival distinction.
    #[test]
    fn rival_possess_lob_accidentally_claims_a_dwelling() {
        let mut w = flat_world();
        let rival_tag = 7u16;
        // Register the tag as rival slot 2 so the claim recolor can
        // resolve its team (owner_team = the wizext var_48 stand-in).
        w.g.rival_ents[2] = rival_tag;
        let house_x = 0x8000u16.wrapping_add(1500);
        let h = w.g.spawn_creator(45, house_x, 0x8000, 3200).expect("house");
        {
            let e = &mut w.g.ent[h];
            e.tick70 = 52; // live village building
            e.act_life = 2000;
            e.f144 = 0; // unclaimed
            e.f80 = 0x700;
            e.f82 = 0x700;
            e.f84 = 0x4000; // the go-live z-extent (features fixup)
            e.f28 |= 2; // the go-live ch1 claim bit (features :2054 fixup)
        }
        let lob = w.g.spawn_spell_lob(1, 0x8000, 0x8000, 3200).expect("lob");
        {
            let e = &mut w.g.ent[lob];
            e.id24 = rival_tag;
            e.f66 = 10;
            e.f69 = 12;
            e.f26 = 200;
            e.f30 = Gen::angle_between(0x8000, 0x8000, house_x, 0x8000);
            e.f32 = 0;
        }
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: false,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        // Fly until impact (life is 21 ticks; the house overlap ends
        // it long before).
        for _ in 0..32 {
            if w.g.ent[lob].flags & 0x400 != 0 {
                break;
            }
            w.g.proj_tick(lob, &ctx);
        }
        assert_ne!(w.g.ent[lob].flags & 0x400, 0, "lob detonated");
        let flash = (1..w.g.ent.len())
            .find(|&j| {
                w.g.ent[j].class64 == 10
                    && w.g.ent[j].model65 == 12
                    && w.g.ent[j].flags & 0x400 == 0
            })
            .expect("the (10,12) claim flash spawned");
        assert_eq!(
            w.g.ent[flash].id24, rival_tag,
            "flash carries the rival tag"
        );
        // One flash tick broadcasts the ch1 claim; the building tick
        // consumes it.
        w.g.effect_tick(flash, &ctx);
        assert_ne!(
            w.g.ent[h].mail[1].1, 0,
            "ch1 claim mail landed on the house"
        );
        w.g.tick_building_live(h, crate::patches::WorldPatches::RETAIL);
        assert_eq!(
            w.g.ent[h].f144, rival_tag,
            "the dwelling is rival-possessed (accidental claim, retail-faithful)"
        );
        assert_eq!(
            w.g.ent[h].type86,
            177 + 2,
            "the claimed flag wears the owner's color (row 177 + team, :30808-09)"
        );
    }

    /// The village LEASH (sub_1F640 :25390-96): the door-radius test
    /// runs BEFORE the fullness test, so a villager anchored to a FULL
    /// house that is still beyond 0x800 keeps its anchor and steers
    /// home — the pull that keeps retail villages clustered around
    /// their dwellings. The broken order (fullness first) dropped the
    /// anchor at ANY distance the moment the home filled, and the
    /// whole village diffused across the map (the population-explosion
    /// dispersal).
    #[test]
    fn full_house_still_pulls_its_villager_home() {
        let mut w = flat_world();
        let h = w.g.spawn_creator(45, 0x8000, 0x8000, 3200).expect("house");
        w.g.ent[h].f128 = 8; // capacity
        w.g.ent[h].f26 = 8; // FULL
        let m =
            w.g.spawn_creature(13, 0x8000 + 0x1000, 0x8000, 3200)
                .expect("feeder");
        w.g.ent[m].f146 = h as u16;
        w.g.ent[m].f63 = 0; // think tick (f63 % v_26 == 0)

        w.g.feeder_wander(m, 78, false);

        assert_eq!(
            w.g.ent[m].f146, h as u16,
            "beyond the door radius the anchor must SURVIVE fullness"
        );
        assert_eq!(w.g.ent[m].tick70, 79, "no walk-in from afar");
        assert_eq!(w.g.ent[h].f26, 8, "occupancy untouched");
        // And it steers home: due west of the house the aim is ~1536
        // (yaw 0 = north, 11-bit circle) — the walk step that runs
        // before the think nudges it a hair off-axis, so allow a small
        // cone. A jitter draw instead would swing ±(85..=340).
        let aim = w.g.ent[m].f34 as i32;
        assert!(
            (aim - 1536).abs() <= 8,
            "the think must re-aim AT the full home, not jitter away (f34 = {aim})"
        );
    }

    /// LIGHTNING STORM, the flock killer. `sub_54520` case 9 (:64125,
    /// remc1hw :60256) scores the CREATURE buckets at yaw 0x71 / pitch
    /// **0x200** — a ±90° pitch cone that no other acquire subtype uses.
    /// The (10,38) cloud fires its (9,9) bolts at a fixed pitch 56
    /// (≈10° down) from 1024 above the terrain and the bolt's whole
    /// reach is `life/3 + 1` steps of 384, so it can never reach the
    /// ground unaided: EVERY storm kill is the acquire snapping the
    /// beam down onto a creature. This fixture is non-vacuous by
    /// construction — the asserted pitch delta is checked to exceed the
    /// shared 0x71 cone, so under it the beam locks nothing and sails
    /// out level "just above the monsters" (the reported mc1hw bug).
    #[test]
    fn storm_bolt_locks_the_flock_below_and_strikes_at_creature_z() {
        use crate::mc1::mobs::MobCtx;

        let mut w = flat_world();
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: true, // keep the human out of the candidate set
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let (cx, cy) = (0x8000u16, 0x8000u16);
        let ground = w.g.ground_z(cx, cy) as i16;

        // The flock: one griffon a tile north of the cloud, on the deck.
        let m =
            w.g.spawn_creature(8, cx, cy.wrapping_sub(256), ground)
                .expect("griffon");
        w.g.ent[m].id24 = 0; // wild
        w.g.ent[m].f58 = 16; // awake — the bucket-scan gate

        // The bolt as the cloud lays it: cloud altitude, yaw due north,
        // the storm's fixed pitch 56, a third of the ctor life.
        let b =
            w.g.spawn_zigzag(cx, cy, ground.wrapping_add(1024))
                .expect("bolt");
        w.g.ent[b].id24 = PLAYER_TARGET;
        w.g.ent[b].act_life /= 3;
        w.g.ent[b].f30 = 0;
        w.g.ent[b].f32 = 56;
        w.g.ent[b].f68 = 10;
        w.g.ent[b].f69 = 23;
        w.g.ent[b].f44 = 2000;

        // Non-vacuity: the griffon sits far outside the shared ±0x71
        // pitch cone, so only case 9's ±0x200 can see it.
        let (tx, ty, tz) = {
            let e = &w.g.ent[m];
            (e.x, e.y, e.z.wrapping_add(e.f78 as i16))
        };
        let dh = Gen::isqrt(Gen::dist2_sq(cx, cy, tx, ty) as u32) as i32;
        let want_pitch = Gen::pitch_toward(ground.wrapping_add(1024), tz, dh);
        let dp = Gen::angdist(56, want_pitch) as u32;
        assert!(
            dp > 0x71,
            "fixture is vacuous: pitch delta {dp} already inside the shared cone"
        );
        assert!(dp <= 0x200, "fixture out of case 9's cone too ({dp})");

        w.g.proj_tick(b, &ctx);

        assert_eq!(
            w.g.ent[b].f146, m as u16,
            "the storm bolt must lock the creature under it"
        );
        assert_eq!(
            (w.g.ent[b].f30, w.g.ent[b].f32),
            (w.g.ent[b].f34, w.g.ent[b].f36),
            "the acquire SNAPS the live heading onto the pick"
        );
        // Unlocked, the beam would hold pitch 56 for its whole
        // 4×384 reach and end ~760 above the deck — the reported
        // "hovers just above the monsters". Locked, it dives to the
        // flock's altitude.
        assert!(
            w.g.ent[b].z <= ground.wrapping_add(256),
            "the strike must reach creature altitude, got z {} (ground {ground})",
            w.g.ent[b].z
        );

        // The endpoint (10,23) flash carries the storm's damage down
        // to the strike point.
        let flash = (1..w.g.ent.len())
            .find(|&j| {
                let e = &w.g.ent[j];
                e.class64 == 10 && e.model65 == 23 && e.flags & 0x400 == 0
            })
            .expect("(10,23) endpoint flash");
        assert_eq!(w.g.ent[flash].f44, 2000, "the flash carries +44 down");
        assert!(
            w.g.ent[flash].z <= ground.wrapping_add(256),
            "the flash must land at the flock, got z {}",
            w.g.ent[flash].z
        );
        let before = w.g.ent[m].act_life;
        w.g.effect_tick(flash, &ctx);
        assert!(
            w.g.ent[m].mail[0].1 >= 2000 || w.g.ent[m].act_life < before,
            "the strike must deliver the storm's 2000 to the creature"
        );
    }

    /// THE AIM-Z BRACKET (`Ent::aim_z` — sub_524C0/sub_524E0
    /// :62503-14): per-tick homing (sub_52550) measures its target at
    /// z + signed +78 EXCEPT model 2, measured RAW. A castle's +78 is
    /// the 0xE000 (−8192) collision marker, so the unguarded lift
    /// steered every homing projectile at a point 8192 UNDER the
    /// mound — the player report: fireballs/meteors dive sharply at
    /// the castle base, with only the (already-guarded) landing
    /// teleport putting the burst at the flag.
    #[test]
    fn homing_steers_at_the_castle_flag_not_under_the_mound() {
        use crate::mc1::mobs::MobCtx;

        let mut w = flat_world();
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: true,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let (cx, cy) = (0x8000u16, 0x8000u16);
        let ground = w.g.ground_z(cx, cy) as i16;

        // A rival castle with the level-1 extents applied — f78 takes
        // the 0xE000 z-center marker (sub_37150).
        let castle = w.g.new_event().expect("castle slot");
        {
            let e = &mut w.g.ent[castle];
            e.class64 = 3;
            e.model65 = 2;
            e.tick70 = 4;
            e.id24 = 3;
            e.x = cx;
            e.y = cy;
            e.z = ground;
        }
        w.g.castle_extents(castle, 1);
        assert_eq!(
            w.g.ent[castle].f78, 0xE000,
            "fixture vacuous without the castle z-center marker"
        );

        // A player fireball 16 tiles west, locked onto the castle.
        let (bx, by, bz) = (cx - 4096, cy, ground + 1024);
        let b = w.g.spawn_fireball(bx, by, bz).expect("fireball");
        w.g.arm_projectile(
            b,
            PLAYER_TARGET,
            3,
            0xFF,
            castle as u16,
            cx,
            cy,
            ground,
            780,
            0,
        );

        w.g.proj_tick(b, &ctx);

        let dh = Gen::isqrt(Gen::dist2_sq(bx, by, cx, cy) as u32) as i32;
        let flag = Gen::pitch_toward(bz, ground, dh);
        let under_mound = Gen::pitch_toward(bz, ground.wrapping_add(0xE000u16 as i16), dh);
        assert_ne!(
            flag, under_mound,
            "fixture vacuous: the two laws agree at this geometry"
        );
        assert_eq!(
            w.g.ent[b].f36, flag,
            "the homing tick must steer at the castle's RAW z (the flag)"
        );
    }

    /// The MC2 twin (sub_65580/sub_655A0 EF:62750-67, the same
    /// model-2 guard — remc2's `model_0x40_64` value key reads
    /// "2 - castle"): the flyer homing tick steers at a castle's RAW
    /// z. The old port guarded on the CLASS byte, so castles (class
    /// 3) took the −8192 lift and dove at the mound exactly like the
    /// MC1 bug.
    #[test]
    fn mc2_flyer_homing_steers_at_the_castle_flag() {
        use crate::mc1::mobs::MobCtx;

        let mut w = mc2_flat_world();
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: true,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let (cx, cy) = (0x8000u16, 0x8000u16);
        let ground = w.g.ground_z(cx, cy) as i16;

        // A rival castle wearing the settled-tick collision layout
        // (the every-other-tick sub_37150 self-heal: extents +
        // f78 = 0xE000).
        let castle = w.g.new_event().expect("castle slot");
        {
            let e = &mut w.g.ent[castle];
            e.class64 = 3;
            e.model65 = 2;
            e.tick70 = 4;
            e.id24 = 2;
            e.x = cx;
            e.y = cy;
            e.z = ground;
            e.max_life = 1000;
            e.act_life = 1000;
            e.f78 = 0xE000;
            e.f80 = 0x8A0;
            e.f82 = 0x8A0;
            e.f84 = 0x4000;
        }

        // A player fireball 16 tiles west, locked onto the castle.
        let (fx, fy, fz) = (cx - 4096, cy, ground + 1024);
        let f = w.g.mc2_spawn_cast_proj(0, fx, fy, fz).expect("fireball");
        w.g.ent[f].id24 = PLAYER_TARGET;
        w.g.ent[f].f146 = castle as u16;

        w.g.mc2_proj_tick(f, &ctx);

        let dh = Gen::isqrt(Gen::dist2_sq(fx, fy, cx, cy) as u32) as i32;
        let flag = Gen::pitch_toward(fz, ground, dh);
        let under_mound = Gen::pitch_toward(fz, ground.wrapping_add(0xE000u16 as i16), dh);
        assert_ne!(
            flag, under_mound,
            "fixture vacuous: the two laws agree at this geometry"
        );
        assert_eq!(
            w.g.ent[f].f36, flag,
            "the MC2 flyer homing tick must steer at the castle's RAW z (the flag)"
        );
    }

    /// The (10,13) RISING SMOKE PUFF (ctor sub_3AAA0, tick sub_257B0
    /// :28443). Two things were wrong at once: the standing fire never
    /// emitted it (a documented skip that kept only the LCG draw), and
    /// the state had NO tick arm — so any imported puff fell through
    /// world.rs's class-10 catch-all and self-killed. In the mc1hw
    /// corpus that made (10,13) the single largest unexplained family.
    #[test]
    fn burning_fire_emits_rising_smoke_that_survives_its_own_tick() {
        use crate::mc1::mobs::MobCtx;

        let mut w = flat_world();
        let ctx = MobCtx {
            px: 0,
            py: 0,
            pz: 0,
            pyaw: 0,
            pmana: 0,
            pdead: true,
            strict: false,
            patches: crate::patches::WorldPatches::RETAIL,
            mc2_turn: 0,
        };
        let (cx, cy) = (0x8000u16, 0x8000u16);
        let ground = w.g.ground_z(cx, cy) as i16;

        let f = w.g.spawn_effect(6, cx, cy, ground).expect("standing fire");
        w.g.ent[f].id24 = 7;
        w.g.ent[f].flags |= 0x10000; // silence the damage broadcast
        // Park it in the shrink window: life < 12 with +26 still up.
        w.g.ent[f].act_life = 11;
        w.g.ent[f].f26 = 6;

        // The exhaust is a 1-in-7 roll; burn ticks until one lands.
        let mut puff = None;
        for _ in 0..40 {
            w.g.ent[f].act_life = 11;
            w.g.ent[f].f26 = 6;
            w.g.effect_tick(f, &ctx);
            puff = (1..w.g.ent.len()).find(|&j| {
                let e = &w.g.ent[j];
                e.class64 == 10 && e.model65 == 13 && e.flags & 0x400 == 0
            });
            if puff.is_some() {
                break;
            }
        }
        let p = puff.expect("the standing fire must exhaust a (10,13) puff");
        assert_eq!(w.g.ent[p].tick70, 13, "the puff runs state 13");
        assert_eq!(w.g.ent[p].act_life, 15, "the fire overrides life to 15");
        assert_eq!(
            w.g.ent[p].f26, 100,
            "+26 = 100 parks it past the drift window"
        );
        assert_eq!(w.g.ent[p].id24, 7, "the puff inherits the fire's owner");

        // One tick: it RISES by the clamped speed and stays alive —
        // before the state-13 arm it was flagged dead on the spot.
        let (z0, speed0) = (w.g.ent[p].z, w.g.ent[p].f126);
        let (x0, y0) = (w.g.ent[p].x, w.g.ent[p].y);
        w.g.effect_tick(p, &ctx);
        assert_eq!(
            w.g.ent[p].flags & 0x400,
            0,
            "the puff must survive its tick"
        );
        assert_eq!(
            w.g.ent[p].f126,
            (speed0 - 4).clamp(64, 128),
            "the rise speed decays 4 a tick into [64, 128]"
        );
        assert_eq!(
            w.g.ent[p].z,
            z0.wrapping_add(w.g.ent[p].f126),
            "the puff rises by the clamped speed"
        );
        assert_eq!(
            (w.g.ent[p].x, w.g.ent[p].y),
            (x0, y0),
            "+26 = 100 means no lateral drift for a fire's smoke"
        );
        assert_eq!(w.g.ent[p].act_life, 14, "pre-decrement life");

        // And it dies on its own clock, not one tick after birth.
        for _ in 0..16 {
            w.g.effect_tick(p, &ctx);
        }
        assert_ne!(w.g.ent[p].flags & 0x400, 0, "the puff expires on its life");
    }

    /// The drop arm (:25396-401 LABEL_36): only INSIDE the door radius
    /// does a full home release its villager — and the release slows
    /// the wander to the accel speed (+126 = +130) until a new home is
    /// acquired (which restores the max speed, :25436-38).
    #[test]
    fn full_house_releases_only_at_the_door_and_slows_the_wanderer() {
        let mut w = flat_world();
        let h = w.g.spawn_creator(45, 0x8000, 0x8000, 3200).expect("house");
        w.g.ent[h].f128 = 8;
        w.g.ent[h].f26 = 8; // FULL
        let m =
            w.g.spawn_creature(13, 0x8000 + 0x400, 0x8000, 3200)
                .expect("feeder");
        w.g.ent[m].f146 = h as u16;
        w.g.ent[m].f63 = 0;

        w.g.feeder_wander(m, 78, false);

        assert_eq!(w.g.ent[m].f146, 0, "at the door of a full home: drop");
        assert_eq!(
            w.g.ent[m].f126, w.g.ent[m].f130,
            "the dropped wanderer slows to the accel speed"
        );

        // On the next think it re-acquires (the house is nearest) and
        // speeds back up to max for the walk home.
        w.g.feeder_wander(m, 78, false);
        assert_eq!(w.g.ent[m].f146, h as u16, "re-acquired the village");
        assert_eq!(
            w.g.ent[m].f126, w.g.ent[m].f128,
            "homing runs at the max speed"
        );
    }

    /// The m14 migrant filter (sub_1FAC0 :25603) selects the nearest
    /// house BEYOND 0xE100000 dist² INSIDE the scan loop — a migrant
    /// standing in a village still emigrates to the distant one. The
    /// broken shape (test the global nearest, bail if it is too close)
    /// left migrants beside their birth village anchorless forever —
    /// they never migrated, never got absorbed, and piled up.
    #[test]
    fn migrant_skips_the_near_village_and_anchors_to_the_far_one() {
        let mut w = flat_world();
        let near =
            w.g.spawn_creator(45, 0x8000 + 0x600, 0x8000, 3200)
                .expect("near house");
        let far =
            w.g.spawn_creator(45, 0x8000 + 0x4000, 0x8000, 3200)
                .expect("far house");
        let m =
            w.g.spawn_creature(14, 0x8000, 0x8000, 3200)
                .expect("migrant");
        w.g.ent[m].f63 = 0;

        w.g.feeder_wander(m, 84, true);

        assert_ne!(
            w.g.ent[m].f146, near as u16,
            "a migrant never anchors inside the 0xE100000 radius"
        );
        assert_eq!(
            w.g.ent[m].f146, far as u16,
            "the nearest house BEYOND the radius is the migration target"
        );
        assert_eq!(w.g.ent[m].f126, w.g.ent[m].f128, "migrates at max speed");
    }

    // ------------------------------------------------------ snapshot

    /// A sim that has been played for a while: pristine state
    /// round-trips through anything, including a codec that dropped
    /// half its fields, so every snapshot assertion below is made
    /// against a world that has actually run.
    ///
    /// Parked ON the micro-world's proximity trigger, so play does not
    /// merely move the carpet — the disposition fires, the crater and
    /// creature allocate, and the pool's `free`/`slot_gen` actually
    /// change. Flying somewhere empty would leave those two identical
    /// to a fresh world and quietly defeat the tests that check them.
    fn played_sim(ticks: usize) -> crate::Simulation {
        let mut sim = crate::Simulation::with_world(flat_world());
        // The same spot `at_trigger()` names, in flyer tile units.
        sim.flyer.x = 100.5;
        sim.flyer.z = 100.5;
        sim.flyer.y = 105.0 / 8.0;
        sim.sync_carpet_from_flyer();
        // Hover on the trigger first. The proximity probe is throttled
        // to every 8th tick, so thrusting away immediately would leave
        // the volume before it ever fires.
        for _ in 0..24 {
            sim.step(&crate::FlightInput::default());
        }
        let fly = crate::FlightInput {
            thrust: 1.0,
            stick_x: 40,
            stick_y: -20,
            ..Default::default()
        };
        for _ in 0..ticks {
            sim.step(&fly);
        }
        sim
    }

    /// The acceptance test in miniature (the full one, on real baked
    /// levels, is `tests/snapshot.rs`): snapshot a played sim, apply
    /// it onto a freshly built one, and require the two to be
    /// indistinguishable — by digest AND by the arrays the digest
    /// cannot see.
    #[test]
    fn snapshot_round_trips_a_played_world() {
        let live = played_sim(120);
        let bytes = live.snapshot();

        let mut restored = crate::Simulation::with_world(flat_world());
        // Fixture validity: the target must START different, or the
        // whole test would pass on a codec that wrote nothing.
        assert_ne!(
            live.state_hash(),
            restored.state_hash(),
            "fixture is wrong: a fresh world already matches the played one"
        );
        restored.restore(&bytes).expect("restore");

        assert_eq!(live.state_hash(), restored.state_hash(), "state hash");
        let (a, b) = (
            live.world.as_ref().unwrap(),
            restored.world.as_ref().unwrap(),
        );
        assert_eq!(a.observable_digest(), b.observable_digest(), "observable");
    }

    /// `SlotGens` hashes to NOTHING (features.rs) and `free` is a
    /// plain `Vec<u16>` whose ORDER is the pool economy — the state
    /// hash is blind to both, so a codec bug there would sail past
    /// the test above. They get their own assertions.
    #[test]
    fn snapshot_carries_what_the_hash_cannot_see() {
        let live = played_sim(120);
        let bytes = live.snapshot();
        let fresh = crate::Simulation::with_world(flat_world());
        let mut restored = crate::Simulation::with_world(flat_world());
        restored.restore(&bytes).expect("restore");

        let g = |s: &crate::Simulation| {
            let w = s.world.as_ref().unwrap();
            (w.g.free.clone(), w.g.slot_gen.0.clone())
        };
        let (live_free, live_gen) = g(&live);
        let (fresh_free, fresh_gen) = g(&fresh);
        let (rest_free, rest_gen) = g(&restored);

        // Fixture validity again: play must have MOVED both, or
        // "restored == live" would hold trivially.
        //
        // Note this is an ORDER difference, not a length one: the
        // crater allocates and then frees itself, so the stack ends
        // the same SIZE with its top permuted. Which is the whole
        // reason `free` is saved verbatim instead of rebuilt from
        // occupancy — a rebuild would match on length and set, and
        // still hand out different slots from here on.
        assert!(
            live_free != fresh_free,
            "fixture is wrong: play left the free stack untouched \
             (len {} vs {})",
            live_free.len(),
            fresh_free.len()
        );
        let bumped = |g: &[u32]| g.iter().filter(|&&v| v != 0).count();
        assert_ne!(
            bumped(&live_gen),
            bumped(&fresh_gen),
            "fixture is wrong: play did not bump any slot generation"
        );

        assert!(
            live_free == rest_free,
            "free stack order is the pool economy, and it did not survive \
             the round trip"
        );
        assert!(
            live_gen == rest_gen,
            "slot generations did not survive the round trip (hash-silent, \
             so nothing else would have caught this)"
        );
    }

    /// The other hash-blind fields, which a digest-derived codec would
    /// also have dropped: `Rec::par3` (hash-excluded), `World::mc2_turn`
    /// (excluded as a function of the tick counter), and the three MC2
    /// cast-window latches, which are hashed only when armed.
    #[test]
    fn snapshot_carries_the_hash_excluded_fields() {
        let mut live = played_sim(20);
        {
            let w = live.world.as_mut().unwrap();
            w.table[0].par3 = 0x5A5A;
            w.mc2_turn = 12345;
            w.player.accel_mc2_factor = 3;
            w.player.invis_strength = 2;
            w.player.metamorph = 19;
        }
        let bytes = live.snapshot();
        let mut restored = crate::Simulation::with_world(flat_world());
        restored.restore(&bytes).expect("restore");

        let w = restored.world.as_ref().unwrap();
        assert_eq!(w.table[0].par3, 0x5A5A, "Rec::par3");
        assert_eq!(w.mc2_turn, 12345, "World::mc2_turn");
        assert_eq!(w.player.accel_mc2_factor, 3);
        assert_eq!(w.player.invis_strength, 2);
        assert_eq!(w.player.metamorph, 19);
    }

    /// A restored sim must not merely LOOK identical — it must go on
    /// producing the same world. This is the divergence test: any
    /// field the codec dropped that feeds a later decision shows up
    /// as a split some ticks down the line, not at restore time.
    #[test]
    fn restored_sim_stays_identical_under_further_ticks() {
        let mut live = played_sim(60);
        let mut restored = crate::Simulation::with_world(flat_world());
        restored.restore(&live.snapshot()).expect("restore");

        let fly = crate::FlightInput {
            thrust: 1.0,
            stick_x: -30,
            ..Default::default()
        };
        for i in 0..600 {
            live.step(&fly);
            restored.step(&fly);
            assert_eq!(
                live.state_hash(),
                restored.state_hash(),
                "diverged {i} ticks after restore"
            );
        }
    }

    #[test]
    fn snapshot_rejects_damaged_streams() {
        use crate::snapshot::SnapshotError;
        let live = played_sim(20);
        let bytes = live.snapshot();
        let mut sim = crate::Simulation::with_world(flat_world());

        let mut bad_magic = bytes.clone();
        bad_magic[0] ^= 0xFF;
        assert!(matches!(
            sim.restore(&bad_magic),
            Err(SnapshotError::BadMagic(_))
        ));

        let mut bad_version = bytes.clone();
        bad_version[4] = 0xEE;
        assert!(matches!(
            sim.restore(&bad_version),
            Err(SnapshotError::Version(_))
        ));

        assert_eq!(
            sim.restore(&bytes[..bytes.len() - 4]),
            Err(SnapshotError::Truncated)
        );

        let mut trailing = bytes.clone();
        trailing.push(0);
        assert_eq!(sim.restore(&trailing), Err(SnapshotError::Trailing(1)));
    }

    /// Coverage proof for the three MC2 cast-window latches
    /// (`accel_mc2_factor`, `invis_strength`, `metamorph`), which were
    /// hash-EXCLUDED until `docs/archive/DESIGN-SAVES.md` prerequisite 2.
    ///
    /// They must be invisible at pristine — that is what keeps every
    /// existing golden byte-stable — and visible the moment they are
    /// armed, or a snapshot codec that silently dropped them would
    /// round-trip "successfully" against the digest. Both halves are
    /// asserted here; the pristine half is the one that will fail
    /// first if someone promotes these to an unconditional hash.
    #[test]
    fn hash_sees_the_mc2_cast_latches_only_when_armed() {
        let base = flat_world().state_hash();

        // Pristine transparency: an untouched world still hashes to the
        // same value it did while the fields were excluded outright.
        assert_eq!(
            base,
            flat_world().state_hash(),
            "the builder must be deterministic for the rest to mean anything"
        );

        let mut speed = flat_world();
        speed.player.accel_mc2_factor = 3;
        assert_ne!(
            base,
            speed.state_hash(),
            "accel_mc2_factor must reach the hash once armed: it gates \
             thrust_cancel/full_stop_cancel_accel before speed_boost is read"
        );

        let mut invis = flat_world();
        invis.player.invis_strength = 2;
        assert_ne!(
            base,
            invis.state_hash(),
            "invis_strength must reach the hash once armed: it drives the \
             per-tier break-on-self-cast law"
        );

        let mut meta = flat_world();
        meta.player.metamorph = 19;
        assert_ne!(
            base,
            meta.state_hash(),
            "metamorph must reach the hash once armed: it hides the carpet \
             and names the model drawn in its place"
        );

        // Distinct latches must not collide with each other either —
        // a single `if any != 0 { .. }` guard would pass the asserts
        // above while conflating the three.
        let mut other = flat_world();
        other.player.invis_strength = 3;
        assert_ne!(
            invis.state_hash(),
            other.state_hash(),
            "the latch VALUE must reach the hash, not merely its armedness"
        );
    }

    fn at_trigger() -> PlayerPose {
        PlayerPose::from_tiles(100.5, 105.0 / 8.0, 100.5, 0.0, 0.0, 0.0)
    }

    /// MC2's level-init hand assignment (`InitialiseSpells_54A50`
    /// EF:38755-62): first enabled index → LEFT, second → RIGHT.
    /// MC2's canonical order is the identity (`spellIndex_D94FF`,
    /// GameUI.cpp:59), so it is always the two lowest owned indices —
    /// Fireball (0) and Possession (1) with every authored level row.
    ///
    /// Player report: "in level 003 the left hand is Beyond Sight and
    /// the right is possession; in 001 it's speed + possession". The
    /// batch grant was running the jar-PICKUP law, which binds left,
    /// then right, then overwrites LEFT for every spell past the
    /// second — leaving left = the LAST granted and right = the
    /// SECOND. This test pins the level-start law; the pickup law is
    /// pinned below it and must stay as it is.
    #[test]
    fn mc2_level_start_hands_are_the_two_lowest_indices() {
        // mc2:003's authored human row.
        let grants: Vec<(u8, i32)> = [0u8, 1, 2, 3, 4, 6, 11, 12]
            .iter()
            .map(|&s| (s, 0i32))
            .collect();
        let mut w = mc2_flat_world();
        w.mc2_grant_plausible(&grants);
        assert_eq!(w.mc2_book.left, 0, "LEFT = Fireball, not the last granted");
        assert_eq!(w.mc2_book.right, 1, "RIGHT = Possession");

        // Order-independent, like MC1's.
        let mut rev = mc2_flat_world();
        let mut back = grants.clone();
        back.reverse();
        rev.mc2_grant_plausible(&back);
        assert_eq!((rev.mc2_book.left, rev.mc2_book.right), (0, 1));

        // Every MC2 world is seeded with 0 and 1 at construction, so a
        // later batch must not disturb the pair no matter what it adds
        // — "always fireball + possession", the player's requirement.
        let mut extra = mc2_flat_world();
        assert_eq!((extra.mc2_book.left, extra.mc2_book.right), (0, 1));
        extra.mc2_grant_plausible(&[(9, 0), (21, 0), (25, 0)]);
        assert_eq!(
            (extra.mc2_book.left, extra.mc2_book.right),
            (0, 1),
            "high-index grants must not steal a hand"
        );

        // The PICKUP law is untouched: collecting a further spell with
        // both hands full overwrites the LEFT hand (EF:55735-49).
        w.mc2_dev_grant_for_test(13);
        assert_eq!(w.mc2_book.left, 13, "a pickup still takes the left hand");
        assert_eq!(w.mc2_book.right, 1, "...and leaves the right alone");
    }

    /// Retail's level-init hand assignment (`sub_3DD50_3E090`
    /// :49213-49254): LEFT/RIGHT = the first two owned spells walked in
    /// BOOK order `byte_99B88` = `[0, 3, 2, 16, 1, ...]`, NOT in
    /// ascending spell id.
    ///
    /// Player report: "you start with fireball + heal, it should be
    /// fireball + possession". The port bound hands incrementally as
    /// spells were granted, and every caller grants ascending, so Heal
    /// (id 1) took the right hand — but Heal is book position 5,
    /// behind Possess, Accelerate and Castle, and can only reach a
    /// hand when nothing above it is owned.
    #[test]
    fn level_start_hands_follow_book_order_not_spell_id() {
        // The mc1:005 owned set.
        let mut w = flat_world();
        w.grant_spells(&[0, 1, 2, 3, 4, 16, 23]);
        assert_eq!(w.player.left, Some(SpellId(0)), "LEFT = Fireball");
        assert_eq!(
            w.player.right,
            Some(SpellId(3)),
            "RIGHT = Possess (book pos 2), NOT Heal (id 1, book pos 5)"
        );

        // Order-independent: retail rebuilds from the owned SET, so the
        // same spells granted in reverse must bind identically.
        let mut rev = flat_world();
        rev.grant_spells(&[23, 16, 4, 3, 2, 1, 0]);
        assert_eq!(
            (rev.player.left, rev.player.right),
            (w.player.left, w.player.right),
            "hand binding must not depend on grant order"
        );

        // Fewer than two owned leaves the other hand empty (retail 255).
        let mut one = flat_world();
        one.grant_spells(&[7]);
        assert_eq!(one.player.left, Some(SpellId(7)));
        assert_eq!(one.player.right, None, "one spell leaves RIGHT empty");

        // Heal DOES reach a hand when it outranks everything owned:
        // book order puts 1 (pos 5) ahead of 7 (pos 11).
        let mut heal = flat_world();
        heal.grant_spells(&[1, 7]);
        assert_eq!(
            (heal.player.left, heal.player.right),
            (Some(SpellId(1)), Some(SpellId(7)))
        );
    }

    /// The m13 archer bolt's constructor uses the DOUBLING sprite
    /// setter (`sub_370A0_37460`, :46274) where every other class-9
    /// ctor uses the plain one — so the arrow carries twice the
    /// collision half-extents. The port applied the plain setter and
    /// gave every archer bolt (m4/m9/m10 creatures + the m15 castle
    /// guard) a half-size hitbox.
    ///
    /// Also pins m9's re-skin (:21957): row 203 is sprite family base
    /// 215 against 195's base 193, but identical 45x60 size and
    /// 5-view fold — cosmetic only, no geometry change.
    ///
    /// Like the boulder, no golden fixture reaches this path: nothing
    /// in level-005 or level-032 ever fires a bolt.
    #[test]
    fn archer_bolt_has_double_extents_and_m9_reskin_is_cosmetic() {
        let mut w = flat_world();
        let (bx, by, bz) = (100 * 256, 100 * 256, (100i16 / 8 + 4) * 256);

        // Row 195 = 45x60 -> plain halves would be 22/22/30.
        let p = w.g.spawn_bolt(bx, by, bz).unwrap();
        assert_eq!(w.g.ent[p].type86, 195);
        let box_of = |w: &World, i: usize| (w.g.ent[i].f80, w.g.ent[i].f82, w.g.ent[i].f84);
        assert_eq!(box_of(&w, p), (44, 44, 60), "the arrow's box is DOUBLED");
        assert_eq!(w.g.ent[p].f78, 30, "+78 is never doubled");

        // m9's override: new billboard family, same geometry.
        w.g.set_sprite_x2(p, 203);
        assert_eq!(w.g.ent[p].type86, 203);
        assert_eq!(box_of(&w, p), (44, 44, 60), "203 changes art, not geometry");

        // Idempotent: retail calls it twice on the same entity (ctor
        // :46274 then thunk :21928) and the box must not reach 4x.
        w.g.set_sprite_x2(p, 203);
        assert_eq!(
            box_of(&w, p),
            (44, 44, 60),
            "repeat calls must not grow the box"
        );

        // The sibling boulder ctor (:46297) stays on the PLAIN setter:
        // row 196 = 128x100 -> undoubled halves.
        let b = w.g.spawn_slow_bolt(bx, by, bz).unwrap();
        assert_eq!(w.g.ent[b].type86, 196);
        assert_eq!(box_of(&w, b), (64, 64, 50), "the boulder is NOT doubled");
    }

    /// The Troll/Ape boulder (class-9 m14, flight state 15) must be
    /// SILENT in flight and speak only through its `(10,0)` impact.
    ///
    /// Player report: the stone-throwers "sound like arrows being
    /// shot". Cause: state 15 was aliased onto state 13's handler,
    /// whose first tick rolls ids 33-36 — the `arrow1`..`arrow4`
    /// samples, and `:63799` is the ONLY site in the whole binary that
    /// emits them. The arrow roll is FAITHFUL for state 13's real
    /// users (the m4/m9/m10 archer creatures and the m15 castle
    /// guard), so the second half of this test pins that it survives:
    /// the fix must not over-correct into silencing the archers.
    ///
    /// No golden fixture reaches state 15 — level-005 and level-032
    /// are full of (5,7) trolls but neither script ever lands a throw
    /// — which is exactly why the alias went unnoticed.
    #[test]
    fn troll_boulder_is_silent_in_flight_and_booms_on_impact() {
        // Drive the WHOLE world so the spawned impact entity ticks
        // too — the boom belongs to the effect, not the projectile.
        // Sounds accumulate because nothing drains them here.
        let fly = |w: &mut World| {
            let mut ids = Vec::new();
            for _ in 0..48 {
                w.tick(away(), PlayerCommand::default());
                ids.extend(w.g.sounds.drain(..).map(|s| s.id));
            }
            ids
        };

        // The boulder: class-9 m14 / state 15, as sub_1AE30 arms it
        // (780 damage, impact descriptor (10,0)).
        let mut w = flat_world();
        let (bx, by, bz) = (100 * 256, 100 * 256, (100i16 / 8 + 4) * 256);
        let b = w.g.spawn_slow_bolt(bx, by, bz).unwrap();
        w.g.arm_projectile(b, 1, 3, 0xFF, 0, bx + 4096, by, bz, 780, 0);
        assert_eq!(w.g.ent[b].tick70, 15, "fixture must be state 15");
        w.g.sounds.clear();
        let ids = fly(&mut w);
        assert!(
            !ids.iter().any(|&id| (33..=36).contains(&id)),
            "the boulder must NOT roll the arrow quartet: {ids:?}"
        );
        assert!(
            ids.contains(&3),
            "the boulder's (10,0) impact must sound (sub_3A490 -> :28114): {ids:?}"
        );

        // The archer bolt: state 13 keeps its arrow roll — faithful
        // retail asset reuse, not a bug to "fix".
        let mut w = flat_world();
        let a = w.g.spawn_bolt(bx, by, bz).unwrap();
        w.g.arm_projectile(a, 1, 3, 0xFF, 0, bx + 4096, by, bz, 250, 0);
        assert_eq!(w.g.ent[a].tick70, 13, "fixture must be state 13");
        w.g.sounds.clear();
        let ids = fly(&mut w);
        assert!(
            ids.iter().any(|&id| (33..=36).contains(&id)),
            "the archer bolt keeps arrow1..arrow4: {ids:?}"
        );
    }

    #[test]
    fn genie_steal_flash_drains_stationary_player() {
        // Repro of the level-042 genie mana-steal gap: a genie-owned
        // ch3 steal flash (state 25) sitting on the player must drain
        // the pool. Big extents isolate the mana path from overlap
        // geometry.
        let mut w = flat_world();
        w.player.mana = 1000;
        w.player.mana_max = 1000;
        w.player.grace = 0; // past spawn invulnerability
        let pose = PlayerPose::from_tiles(100.5, 105.0 / 8.0, 100.5, 0.0, 0.0, 0.0);
        let flash =
            w.g.spawn_effect(25, 100u16 << 8, 100u16 << 8, 800)
                .expect("flash slot");
        w.g.ent[flash].id24 = 9; // a non-player owner (a "genie")
        w.g.ent[flash].f44 = 3000;
        w.g.ent[flash].f80 = 30000;
        w.g.ent[flash].f82 = 30000;
        w.g.ent[flash].f84 = 30000;
        let before = w.player.mana;
        // Two ticks: the flash writes ch3 on its first tick, the apply
        // pass drains on the same/next.
        w.tick(pose, PlayerCommand::default());
        w.tick(pose, PlayerCommand::default());
        assert!(
            w.player.mana + 500 < before,
            "genie steal must drain the player (was {before}, now {})",
            w.player.mana
        );
    }

    #[test]
    fn genie_seeker_end_to_end_drains_stationary_player() {
        // The genie's actual steal seeker (m8 projectile, payload 3000,
        // detonating into the ch3 flash 25) fired at a stationary player
        // must land a drain.
        let mut w = flat_world();
        let pose = PlayerPose::from_tiles(100.5, 105.0 / 8.0, 100.5, 0.0, 0.0, 0.0);
        let (px, py, pz) = (25728u16, 25728u16, 3360i16);
        w.tick(pose, PlayerCommand::default());
        w.player.mana = 1000;
        w.player.mana_max = 1000;
        w.player.grace = 0;
        let before = w.player.mana;
        // Fire from 3 tiles west, aimed at the player.
        let seeker = w.g.spawn_seeker(px - 3 * 256, py, pz).expect("seeker slot");
        w.g.arm_projectile(seeker, 9, 3, 0xFF, PLAYER_TARGET, px, py, pz, 3000, 25);
        let mut min_mana = before;
        for _ in 0..12 {
            w.tick(pose, PlayerCommand::default());
            min_mana = min_mana.min(w.player.mana);
        }
        assert!(
            min_mana + 500 < before,
            "one seeker should land a drain (min {min_mana}, before {before})"
        );
    }

    #[test]
    fn invincibility_is_life_only_mana_steal_still_drains() {
        // God-mode must NOT block the genie mana steal (ch3). Life stays
        // immune; mana drains.
        let mut w = flat_world();
        w.invincible = true;
        w.player.mana = 1000;
        w.player.mana_max = 1000;
        w.player.grace = 0;
        let life_before = w.player.life;
        let pose = PlayerPose::from_tiles(100.5, 105.0 / 8.0, 100.5, 0.0, 0.0, 0.0);
        let flash =
            w.g.spawn_effect(25, 100u16 << 8, 100u16 << 8, 800)
                .expect("flash slot");
        w.g.ent[flash].id24 = 9;
        w.g.ent[flash].f44 = 3000;
        w.g.ent[flash].f80 = 30000;
        w.g.ent[flash].f82 = 30000;
        w.g.ent[flash].f84 = 30000;
        w.tick(pose, PlayerCommand::default());
        w.tick(pose, PlayerCommand::default());
        assert!(
            w.player.mana < 500,
            "steal drains even under invincibility (was 1000, now {}) — not the old wipe-all",
            w.player.mana
        );
        assert_eq!(w.player.life, life_before, "life stays immune");
        assert_eq!(w.player.state, LifeState::Alive, "still can't be killed");
    }

    #[test]
    fn hidden_worlds_spell20_stats_diverge_only_at_row_20() {
        // Fire Storm (20) → homing meteor is the ONLY table divergence
        // (SURVEY-MC1HW §3b): count 51→26, castle_req 12000→60000,
        // damage 24464→5000. Every other row equals base MC1 — the
        // guard that keeps MC1 goldens pinned.
        let mc1 = crate::mc1::spells::spells(GameId::Mc1);
        let hw = crate::mc1::spells::spells(GameId::Mc1Hw);
        for i in 0..SPELL_COUNT {
            if i == 20 {
                continue;
            }
            assert_eq!(mc1[i], hw[i], "spell {i} must match base MC1");
        }
        assert_eq!(hw[20].count, 26, "HW burst count");
        assert_eq!(hw[20].castle_req, 60000, "HW castle req");
        assert_eq!(hw[20].damage, 5000, "HW damage");
        assert_eq!(mc1[20].count, 51, "base count untouched");
        assert_eq!(mc1[20].damage, 24464, "base damage untouched");
    }

    #[test]
    fn hidden_worlds_verbset_wiring_preserves_discriminants() {
        use crate::verbs::{TargetingVerb, VerbSet};
        assert_eq!(GameId::Mc1Hw.verbs().targeting, TargetingVerb::Mc1Hw);
        assert_eq!(GameId::Mc1.verbs().targeting, TargetingVerb::Mc1);
        assert_eq!(GameId::Mc2.verbs().targeting, TargetingVerb::Mc2);
        // The HW column is the MC1 column with only targeting flipped.
        assert_eq!(VerbSet::MC1HW.awake, VerbSet::MC1.awake);
        assert_eq!(VerbSet::MC1HW.flight, VerbSet::MC1.flight);
        assert_eq!(VerbSet::MC1HW.commit_gate, VerbSet::MC1.commit_gate);
        // Mc1/Mc2 discriminants MUST precede Mc1Hw: the VerbSet feeds the
        // state hash, so inserting the HW variant anywhere but last would
        // move every MC2 golden.
        assert!((TargetingVerb::Mc1 as u8) < (TargetingVerb::Mc1Hw as u8));
        assert!((TargetingVerb::Mc2 as u8) < (TargetingVerb::Mc1Hw as u8));
    }

    #[test]
    fn hidden_worlds_firewall_child_homes_in_the_widened_cone() {
        // The m16 Fire Storm child (state 17) runs acquire case 0x10 in
        // HW (yaw cone 0x100) but has NO acquire case in base MC1. A
        // creature at yaw offset 0xA0 (> 0x71, < 0x100), pitch aligned,
        // is picked up only under HW (SURVEY-MC1HW §3a).
        fn acquires(game: GameId) -> bool {
            let planes = Planes {
                height: vec![0; 0x10000],
                tile_type: vec![5; 0x10000],
                shading: vec![32; 0x10000],
                angle: vec![5; 0x10000],
                ceiling: Vec::new(),
            };
            let mut w = World::new_for_game(planes, &[], 1, assets(), game);
            let (bx, by, bz) = (100u16 << 8, 100u16 << 8, 1000i16);
            let bolt = w.g.spawn_firewall_bolt(bx, by, bz).expect("bolt slot");
            w.g.ent[bolt].id24 = PLAYER_TARGET;
            // A live class-5 creature 10 tiles east, same altitude.
            let (cx, cy) = (110u16 << 8, 100u16 << 8);
            let cre = w.g.new_event().expect("creature slot");
            {
                let c = &mut w.g.ent[cre];
                c.class64 = 5;
                c.f58 = 1; // awake / alive
                c.act_life = 100;
                c.tick70 = 1; // != 120 (the asleep state)
                c.id24 = 7; // not the bolt's owner
                c.f78 = 0;
                c.x = cx;
                c.y = cy;
                c.z = bz;
            }
            // Aim so the creature sits exactly 0xA0 off the bolt's yaw.
            let a = Gen::angle_between(bx, by, cx, cy);
            w.g.ent[bolt].f30 = (a + 0xA0) & 0x7FF;
            w.g.ent[bolt].f32 = 0;
            w.g.ent[bolt].f146 = 0;
            let ctx = MobCtx {
                px: 10 << 8,
                py: 10 << 8,
                pz: 0,
                pyaw: 0,
                pmana: 0,
                pdead: false,
                strict: false,
                patches: crate::patches::WorldPatches::RETAIL,
                mc2_turn: 0,
            };
            w.g.proj_tick(bolt, &ctx);
            w.g.ent[bolt].f146 != 0
        }
        assert!(
            acquires(GameId::Mc1Hw),
            "HW firewall child homes (case 0x10, cone 0x100)"
        );
        assert!(
            !acquires(GameId::Mc1),
            "base MC1 firewall child flies straight (no case 16)"
        );
    }

    #[test]
    fn wall_of_fire_punches_through_rebound_in_base_mc1() {
        // sub_52770's deflect arm whitelists impact pairs: base MC1
        // accepts (10,1)/(10,17) only (:62713), so the (10,53) Wall of
        // Fire bolt hits a deflecting victim straight through the
        // shield — silently, no debit (:62751-55) — the anti-griffon
        // spell. HIDDEN.EXE whitelists (10,53) too (the homing meteor;
        // the single compare added to the shared handler, 0x52BF9-
        // 0x52C03), so the same cast deflects in HW. The m0 fireball
        // rides sub_52B30's UNGATED arm (:62847-88) and deflects in
        // both games — the control separating law wiring from fixture.
        use crate::mc1::mobs::PLAYER_TARGET;
        fn shoot(game: GameId, firewall: bool) -> (bool, i32, bool) {
            let planes = Planes {
                height: vec![100; 0x10000],
                tile_type: vec![5; 0x10000],
                shading: vec![32; 0x10000],
                angle: vec![5; 0x10000],
                ceiling: Vec::new(),
            };
            let mut w = World::new_for_game(planes, &[], 1, assets(), game);
            let (bx, by, bz) = (100u16 << 8, 100u16 << 8, 4000i16);
            let bolt = if firewall {
                w.g.spawn_firewall_bolt(bx, by, bz)
            } else {
                w.g.spawn_fireball(bx, by, bz)
            }
            .expect("bolt slot");
            {
                let e = &mut w.g.ent[bolt];
                e.id24 = PLAYER_TARGET;
                e.f30 = 0;
                e.f34 = 0;
                e.f32 = 0;
                e.f36 = 0;
                // The cast stamps the impact pair + cost-per-shot
                // (cast_firewall :66158 / the m0 fireball's (10,0)).
                e.f68 = 10;
                e.f69 = if firewall { 53 } else { 0 };
                e.f44 = 500;
                e.f140 = 400;
            }
            // A deflecting body parked on the flight line (yaw 0 =
            // -y): solid bit 8 + the attack-state deflection bit
            // 0x8000 (:23552) + a deep shield pool.
            let vic = w.g.new_event().expect("victim slot");
            {
                let c = &mut w.g.ent[vic];
                c.class64 = 5;
                c.model65 = 8;
                c.act_life = 30000;
                c.max_life = 30000;
                c.f58 = 1;
                c.tick70 = 120;
                c.id24 = 7;
                c.flags |= 8 | 0x8000;
                c.f140 = 1_000_000;
                c.f78 = 0;
                c.f80 = 512;
                c.f82 = 512;
                c.f84 = 512;
            }
            w.g.link(vic, bx, by.wrapping_sub(640), bz);
            let ctx = MobCtx {
                px: 10 << 8,
                py: 10 << 8,
                pz: 0,
                pyaw: 0,
                pmana: 0,
                pdead: false,
                strict: false,
                patches: crate::patches::WorldPatches::RETAIL,
                mc2_turn: 0,
            };
            let mut deflected = false;
            for _ in 0..5 {
                w.g.proj_tick(bolt, &ctx);
                let e = &w.g.ent[bolt];
                if e.flags & 0x400 != 0 {
                    break; // exploded — the plain hit
                }
                if e.f146 == PLAYER_TARGET && e.id24 == 7 {
                    deflected = true;
                    break;
                }
            }
            let cloud = (1..w.g.ent.len()).any(|j| {
                w.g.ent[j].class64 == 10
                    && w.g.ent[j].model65 == 53
                    && w.g.ent[j].flags & 0x400 == 0
            });
            (deflected, w.g.ent[vic].f140, cloud)
        }
        let (deflected, mana, cloud) = shoot(GameId::Mc1, true);
        assert!(!deflected, "base MC1 Wall of Fire punches through Rebound");
        assert_eq!(mana, 1_000_000, "the refusal is silent — no shield debit");
        assert!(cloud, "the napalm cloud erupts ON the deflector");
        let (deflected, mana, _) = shoot(GameId::Mc1Hw, true);
        assert!(deflected, "the HW meteor (10,53) deflects off Rebound");
        assert_eq!(mana, 1_000_000 - 100, "the deflection quarters +140");
        let (deflected, ..) = shoot(GameId::Mc1, false);
        assert!(deflected, "the m0 fireball's ungated arm still deflects");
    }

    #[test]
    fn castle_on_water_spares_the_courtyard_kraken() {
        // The live painter leaves the yard's water ALIVE (sub_285C0
        // :30550 — zero-delta cells are never touched): a kraken (m6,
        // exempt from the footprint kill, :51753) caught between the
        // rising walls survives the build, swimming its pond — the
        // retail "krakens get trapped between the towers and
        // survive". Before the flatten-law split the yard's tile_type
        // was stenciled to land and the water-only mover rule
        // (:21225-91) killed it on its first boundary crossing.
        let planes = Planes {
            height: vec![0; 0x10000],
            tile_type: vec![0; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![0; 0x10000],
            ceiling: Vec::new(),
        };
        // A 9x9 castle row: 0x59 wall ring + a 7x7 water yard.
        let grid = vec![0u8; 1024];
        let mut dat = Vec::new();
        for row in 0..9u8 {
            dat.push(9);
            for col in 0..9u8 {
                let edge = row == 0 || row == 8 || col == 0 || col == 8;
                dat.push(if edge { 0x59 } else { 0x07 });
            }
            dat.push(0);
        }
        let mut tab = Vec::new();
        tab.extend_from_slice(&0u32.to_le_bytes());
        tab.extend_from_slice(&[0, 0]);
        for _ in 1..8 {
            tab.extend_from_slice(&0u32.to_le_bytes());
            tab.extend_from_slice(&[9, 9]);
        }
        let assets = FeatureAssets::parse(&grid, &tab, &dat).unwrap();
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 5,
            model: 6,
            x: 112,
            y: 110,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets);
        w.set_invincible(true);
        let k = find_slot(&w, 5, 6);
        let p =
            w.g.spawn_creator(42, 112 << 8, 110 << 8, 0)
                .expect("painter slot");
        w.g.ent[p].f71 = 1;
        w.g.ent[p].flags |= 0x10000; // the kill-bit commit painter
        let pose = firing_line();
        for _ in 0..200 {
            w.tick(pose, PlayerCommand::default());
        }
        assert!(
            w.g.ent[k].flags & 0x400 == 0 && w.g.ent[k].act_life > 0,
            "the yard kraken swims its pond alive"
        );
        assert_eq!(
            w.g.t.tile_type[crate::engine::features::tile(112, 110)],
            0,
            "the yard centre keeps its water type"
        );
    }

    #[test]
    fn hidden_worlds_firewall_bolt_is_the_meteor_and_copies_damage() {
        // The HW ctor swap (sub_3A5F0, hw:42474) gives the m16 bolt
        // the meteor sprite 76 (base sub_3A270 :46353 = fireball 42),
        // and the state-17 explode copies the bolt's +44 into the
        // (10,53) cloud (hw:58859) — HW-only; base MC1's cloud keeps
        // its ctor 100 (the banked base +44-copy question).
        fn sprite_and_cloud_f44(game: GameId) -> (u16, u16) {
            let planes = Planes {
                height: vec![0; 0x10000],
                tile_type: vec![5; 0x10000],
                shading: vec![32; 0x10000],
                angle: vec![5; 0x10000],
                ceiling: Vec::new(),
            };
            let mut w = World::new_for_game(planes, &[], 1, assets(), game);
            let (bx, by, bz) = (100u16 << 8, 100u16 << 8, 1000i16);
            let bolt = w.g.spawn_firewall_bolt(bx, by, bz).expect("bolt slot");
            let sprite = w.g.ent[bolt].type86;
            {
                let e = &mut w.g.ent[bolt];
                e.id24 = PLAYER_TARGET;
                e.f44 = 5000;
                e.f68 = 10;
                e.f69 = 53;
                e.act_life = 0; // expire on the next flight tick
            }
            let ctx = MobCtx {
                px: 10 << 8,
                py: 10 << 8,
                pz: 0,
                pyaw: 0,
                pmana: 0,
                pdead: false,
                strict: false,
                patches: crate::patches::WorldPatches::RETAIL,
                mc2_turn: 0,
            };
            w.g.proj_tick(bolt, &ctx);
            let cloud = (1..w.g.ent.len())
                .find(|&j| w.g.ent[j].class64 == 10 && w.g.ent[j].model65 == 53)
                .expect("napalm cloud spawned");
            (sprite, w.g.ent[cloud].f44)
        }
        assert_eq!(
            sprite_and_cloud_f44(GameId::Mc1Hw),
            (76, 5000),
            "HW: meteor sprite, row damage copied into the cloud"
        );
        assert_eq!(
            sprite_and_cloud_f44(GameId::Mc1),
            (42, 5000),
            "base MC1: fireball sprite, and the +44 copy runs here \
             too (:62770 — mc1l5 take: 191/tick = 24464/128 victim \
             slope under the recorded wall)"
        );
    }

    #[test]
    fn walls_gate_the_player_slide_block_and_corner() {
        // A north-south type-8 wall line at tile x=120, plus an east-
        // west line at tile y=101 forming a corner.
        let mut planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        for y in 0..=255 {
            planes.tile_type[tile(120, y)] = 8;
        }
        for x in 0..=255 {
            planes.tile_type[tile(x, 101)] = 8;
        }
        let w = World::new(planes, &[], 1, assets());

        // Oblique approach hugging the wall: the eastward cardinal
        // slide still lands on the wall tile, the southward one
        // succeeds — the player skims along the wall without crossing.
        let slid = w
            .player_wall_gate((119.95, 99.5, 12.5), (120.85, 99.9, 12.5))
            .expect("oblique move slides");
        assert!(slid.0 < 120.0, "never crosses the wall line, x={}", slid.0);
        assert!(slid.1 > 99.5, "slides south along the wall, z={}", slid.1);

        // Farther out, the blocked-cardinal retry shortens the move
        // toward the wall instead (authentic: the scaled slide along
        // the move's own cardinal lands short of the wall tile).
        let short = w
            .player_wall_gate((119.2, 99.5, 12.5), (120.1, 99.9, 12.5))
            .expect("shortened approach");
        assert!(
            short.0 < 120.0 && short.0 > 119.2,
            "shortened, x={}",
            short.0
        );

        // Head-on at high altitude (way above the wall's +48 crest):
        // the aligned cardinal contributes a zero-length slide — the
        // move is voided in place. Walls block at ANY altitude.
        let stuck = w
            .player_wall_gate((119.5, 99.5, 30.0), (120.5, 99.5, 30.0))
            .expect("head-on voids in place");
        assert!(stuck.0 < 120.0, "altitude does not bypass, x={}", stuck.0);

        // Diagonal into the inside corner: both cardinal slides land
        // on wall tiles — the whole move is discarded.
        assert!(
            w.player_wall_gate((119.8, 100.8, 12.5), (120.2, 101.2, 12.5))
                .is_none(),
            "corner discards the whole move"
        );

        // No wall involved: the move passes through bit-identical.
        let free = w
            .player_wall_gate((110.0, 99.0, 12.5), (110.3, 99.2, 12.5))
            .expect("free move");
        assert_eq!(free, (110.3, 99.2, 12.5));
    }

    #[test]
    fn the_flyer_never_crosses_a_wall() {
        let mut planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        for y in 0..=255 {
            planes.tile_type[tile(120, y)] = 8;
            planes.height[tile(120, y)] = 148; // the wall's +48 crest
        }
        let w = World::new(planes, &[], 1, assets());
        let mut sim = crate::Simulation::with_world(w);
        sim.flyer.x = 117.0;
        sim.flyer.z = 99.5;
        sim.flyer.y = 30.0; // far above the crest
        sim.flyer.yaw = std::f32::consts::FRAC_PI_2; // facing +x (east)
        sim.flyer.pitch = 0.0;
        sim.sync_carpet_from_flyer(); // flyer set directly → re-seed
        let thrust = crate::FlightInput {
            thrust: 1.0,
            ..Default::default()
        };
        for _ in 0..600 {
            sim.step(&thrust);
            assert!(sim.flyer.x < 120.0, "wall crossed at x={}", sim.flyer.x);
        }
        assert!(
            sim.flyer.x > 119.0,
            "the flyer did reach the wall, x={}",
            sim.flyer.x
        );
    }

