    // ---- player spells ------------------------------------------------------

    #[test]
    fn casting_fireball_spawns_a_projectile_and_deducts_mana() {
        let mut w = flat_world();
        // A fresh world's book is EMPTY (the retail human grant is
        // availability ∩ collected — no campaign store, no spells).
        let lv = w.loadout();
        assert!(!lv.owned.iter().any(|&o| o), "fresh book starts empty");
        assert_eq!((lv.left, lv.right), (None, None));
        w.grant_spells(&[0, 3]);
        let lv = w.loadout();
        assert!(lv.owned[0] && lv.owned[3], "granted");
        assert_eq!(
            (lv.left, lv.right),
            (Some(0), Some(3)),
            "auto-fill L/R (:49246-54)"
        );
        let fire = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(firing_line(), fire);
        // THE CAST-PHASE LAW: the press only ARMS the spell token
        // (f26 = count at the wizard pass, above the token slots);
        // the token's own tick fires one frame later — corpus:
        // 257/257 l0 + 371/371 l32 arms spawn at arm+1.
        assert_eq!(count(&w, 9, 0), 0, "the press edge only arms");
        assert_eq!(w.loadout().mana, 1000, "no debit at the command site");
        assert!(w.loadout().cooldown[0] > 0.0, "burst window armed");
        w.tick(firing_line(), fire); // held: the token fires the arm
        assert_eq!(count(&w, 9, 0), 1, "the token fires at arm+1");
        // The debit and the spawn land TOGETHER: the token writes the
        // delta (sub_55E80) and the wizard pass applies it the same
        // frame (l0 trace: mana 950 on the spawn record).
        assert_eq!(
            w.loadout().mana,
            800,
            "the full 200 debit landed with the spawn"
        );
        // Fireball is EDGE-triggered (autofire is spell 23's alone):
        // holding adds nothing; a fresh press past the burst does.
        for _ in 0..8 {
            w.tick(firing_line(), fire);
        }
        assert_eq!(
            count(&w, 9, 0) + w.combat_stats().1 as usize,
            1,
            "held fire never re-casts"
        );
        w.tick(firing_line(), PlayerCommand::default()); // release
        w.tick(firing_line(), fire); // re-press: arms
        w.tick(firing_line(), fire); // the token fires
        let total = count(&w, 9, 0) + w.combat_stats().1 as usize;
        assert_eq!(total, 2, "release + re-press casts again (at arm+1)");
        // Below the possess gate nothing fires.
        let mut w2 = flat_world();
        w2.player.mana = 100;
        w2.tick(firing_line(), fire);
        assert_eq!(count(&w2, 9, 0), 0, "mana-gated cast");
    }

    #[test]
    fn jar_pickup_grants_auto_equips_and_keeps_the_slot() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        // A class-12 jar carrying spell 7 (Meteor) via its model.
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 112,
            y: 116,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        assert!(!w.loadout().owned[7]);
        assert_eq!(w.live_poses().iter().filter(|p| p.class == 12).count(), 1);
        let (free0, _) = w.debug_pool();
        // Fly onto the jar (ground 100*32 = 3200 engine units).
        let on_jar = PlayerPose::level((112 << 8) + 128, (116 << 8) + 128, 3260, 0);
        for _ in 0..4 {
            w.tick(on_jar, PlayerCommand::default());
        }
        let lv = w.loadout();
        assert!(lv.owned[7], "the jar granted its spell");
        assert_eq!(lv.left, Some(7), "auto-equipped LEFT (:64855)");
        let (free1, _) = w.debug_pool();
        assert_eq!(free0, free1, "the manifestation keeps the jar's pool slot");
        assert!(
            w.live_poses().iter().all(|p| p.class != 12),
            "the picked-up jar no longer renders"
        );
        // Re-overlap: no duplicate, the manifestation stays (:64843).
        for _ in 0..4 {
            w.tick(on_jar, PlayerCommand::default());
        }
        assert_eq!(w.debug_pool().0, free1);
    }

    /// In play a resting jar rides its tile's ground — the ruled
    /// deviation (DEVIATIONS.md "class12_tick jar ground-snap"): HW
    /// authors jars that later shaping buries unpickably, and
    /// earth-shaping spells would leave jars floating. In
    /// strict-retail mode (conformance imports) the snap is OFF:
    /// retail's reshape walk default-skips class 12 (:51729) and the
    /// HW recordings show a jar holding its z for hundreds of ticks
    /// over lowered ground — replayed retail state must do the same.
    #[test]
    fn jars_ride_terrain_in_play_but_not_under_strict_retail() {
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let mut w = World::new(planes, &things, 1, assets());
        w.set_patches(crate::patches::WorldPatches::LEGACY);
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        w.tick(away, PlayerCommand::default());
        let jar = (1..w.g.ent.len())
            .find(|&i| w.g.ent[i].class64 == 12 && w.g.ent[i].flags & 0x400 == 0)
            .expect("the placed jar exists");
        let (x, y) = (w.g.ent[jar].x, w.g.ent[jar].y);
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "spawns on ground"
        );

        // Raise the ground under it: in play the jar rides up.
        let (tx, ty) = ((x >> 8) as usize, (y >> 8) as usize);
        for dy in 0..2 {
            for dx in 0..2 {
                w.g.t.height[(ty + dy) % 256 * 256 + (tx + dx) % 256] = 140;
            }
        }
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "raised ground lifts the jar in play"
        );
        let riding_z = w.g.ent[jar].z;

        // Strict-retail (a conformance import replay): the snap is
        // off — lowering the ground leaves the jar hovering at its
        // old z, exactly like the retail recordings.
        w.strict_retail = true;
        for dy in 0..2 {
            for dx in 0..2 {
                w.g.t.height[(ty + dy) % 256 * 256 + (tx + dx) % 256] = 40;
            }
        }
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z, riding_z,
            "strict-retail keeps the jar hovering at its old z"
        );

        // Back in play mode the snap resumes and drops it to ground.
        w.strict_retail = false;
        w.tick(away, PlayerCommand::default());
        assert_eq!(
            w.g.ent[jar].z,
            w.g.ground_z(x, y) as i16,
            "play mode re-grounds it"
        );
    }

    /// The jar ground-snap deviation over real content: on baked HW
    /// level 0 (the original buried-jar offender) every placed jar
    /// sits AT the shaped ground within one played tick — never
    /// buried under shaping, never hovering. Self-skips without
    /// baked data.
    #[test]
    fn hw_placed_jars_sit_on_ground_in_play() {
        let root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../baked");
        let lp = root.join("mc1hw/level-000.mgcl");
        if !lp.exists() {
            return;
        }
        let pkg: mgc_formats::LevelPackage =
            mgc_formats::mgcl::read(std::fs::File::open(lp).unwrap()).unwrap();
        let bundle = mgc_formats::bundle::Bundle::load(&root.join("assets/mc1-arctic")).unwrap();
        let terrain = pkg.terrain.as_ref().unwrap();
        let planes = Planes {
            height: terrain.height.clone(),
            tile_type: terrain.tile_type.clone(),
            shading: terrain.shading.clone().unwrap(),
            angle: terrain.angle.clone().unwrap(),
            ceiling: Vec::new(),
        };
        let assets = FeatureAssets::parse(
            bundle.search.as_ref().unwrap(),
            bundle.build_tab.as_ref().unwrap(),
            bundle.build_dat.as_ref().unwrap(),
        )
        .unwrap();
        let seed = pkg.gen_params.as_ref().map_or(0, |g| g.seed);
        let mut w = World::new_for_game(planes, &pkg.things.things, seed, assets, GameId::Mc1Hw);
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        w.tick(away, PlayerCommand::default());
        let mut jars = 0;
        for i in 1..w.g.ent.len() {
            let e = &w.g.ent[i];
            if e.class64 == 12 && e.flags & 0x400 == 0 {
                jars += 1;
                assert_eq!(
                    e.z,
                    w.g.ground_z(e.x, e.y) as i16,
                    "jar slot {i} at ({}, {}) sits on shaped ground",
                    e.x,
                    e.y
                );
            }
        }
        assert!(jars > 0, "level 0 places jars");
    }

    /// With `prune_owned_jars` on, a placed jar whose spell the player
    /// already owns self-culls — retail leaves such uncollectable jars
    /// in the world forever. Faithful default (off) keeps them.
    #[test]
    fn owned_spell_jars_are_pruned_when_enabled() {
        use crate::mc1::spells::SpellId;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        // A placed class-12 jar carrying spell 7, far from the carpet.
        let things = vec![Thing {
            slot: 0,
            kind: ThingKind::Entity,
            class: 12,
            model: 7,
            x: 200,
            y: 200,
            dis_id: 0,
            swi_sz: 0,
            swi_id: 0,
            parent: 0,
            child: 0,
            par3: None,
        }];
        let jars = |w: &World| {
            w.debug_pool()
                .1
                .into_iter()
                .filter(|e| e.class == 12 && e.state < MANIFEST_BASE && e.flags & 0x400 == 0)
                .count()
        };

        // Faithful default: the jar of an already-owned spell stays.
        let mut keep = World::new(planes.clone(), &things, 1, assets());
        keep.grant_spell(SpellId(7));
        let away = PlayerPose::level(10 << 8, 10 << 8, 3260, 0);
        for _ in 0..8 {
            keep.tick(away, PlayerCommand::default());
        }
        assert_eq!(
            jars(&keep),
            1,
            "off by default: the uncollectable jar remains"
        );

        // With the improvement on, the same jar is removed.
        let mut prune = World::new(planes, &things, 1, assets());
        prune.set_prune_owned_jars(true);
        prune.grant_spell(SpellId(7));
        assert_eq!(jars(&prune), 1, "jar present before it ticks");
        for _ in 0..8 {
            prune.tick(away, PlayerCommand::default());
        }
        assert_eq!(jars(&prune), 0, "the owned-spell jar self-culls");
    }

    #[test]
    fn accelerate_directions_are_mutually_exclusive() {
        use crate::mc1::spells::SpellId;
        let mut w = flat_world();
        // Toggle semantics under test, not the economy — the real
        // pool (base 1000) can't fund back-to-back 1000-cost arms.
        w.set_dev_spells(true);
        let equip = PlayerCommand {
            equip_left: Some(SpellId(2)),
            equip_right: Some(SpellId(21)),
            ..Default::default()
        };
        w.tick(away(), equip);
        assert_eq!(w.accel_override(), None, "no override at rest");
        // Forward: ±3.0 while the button is held ("hold down the
        // mouse button to achieve maximum speed").
        let fwd = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "held = 3.0 (:65169)");
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "still held = still 3.0");
        // Released: the channel keeps propelling at 2.0.
        w.tick(away(), PlayerCommand::default());
        assert_eq!(w.accel_override(), Some(2.0), "released = 2.0 channel");
        // Opposite activation force-clears forward (:55871/:55914).
        let back = PlayerCommand {
            fire_right: true,
            ..Default::default()
        };
        w.tick(away(), back);
        assert_eq!(w.player.accel, -1, "backward took over");
        assert_eq!(w.accel_override(), Some(-3.0), "negative held backward");
        let m2 = w.player.owned[2] as usize;
        assert_eq!(w.g.ent[m2].f26, 0, "forward's charge force-cleared");
        // The resisting thrust input cancels instantly (manual: the
        // down cursor; forward thrust for the backward spell).
        w.thrust_cancel(1.0);
        assert_eq!(w.accel_override(), None, "brake input kills the channel");
        // The veto also blocks re-triggering within the same tick.
        w.tick(away(), back);
        assert_eq!(w.accel_override(), None, "vetoed re-trigger");
        // Next tick (no veto) it channels again, then drains after
        // release (count 251) back to no override.
        w.tick(away(), back);
        assert_eq!(w.accel_override(), Some(-3.0));
        for _ in 0..252 {
            w.tick(away(), PlayerCommand::default());
        }
        assert_eq!(w.accel_override(), None, "expired burst drops the override");
        assert_eq!(w.player_speed_boost(), 0.0);
    }

    /// The sustained Accelerate is NOT free: `sub_55E80` (:64936,
    /// live in remc2 as `sub_68DE0`) debits the full cost on every
    /// tick the burst sits at full, and a dry pool drops the flyer
    /// from 3x to 2x for the rest of the burst instead of cancelling
    /// it. No `dev_spells` here — that pin no-ops both the gate and
    /// the debit, which is exactly how this went unnoticed.
    #[test]
    fn held_accelerate_drains_mana_every_tick() {
        use crate::mc1::spells::SpellId;
        let mut w = flat_world();
        w.grant_spell(SpellId(2));
        let cost = crate::mc1::spells::SPELLS[2].possess_mana;
        // The intrinsic base pool IS one cast (both are 1000), and the
        // ceiling is re-censused every tick from claimed entities, so
        // an unclaimed test world can never fund a second re-arm —
        // which makes this world the sharpest probe there is: before
        // the fix the hold stayed at 3.0 forever on an empty pool.
        assert_eq!(w.player.mana, cost, "base pool funds exactly one arm");
        w.tick(
            away(),
            PlayerCommand {
                equip_left: Some(SpellId(2)),
                ..Default::default()
            },
        );
        let fwd = PlayerCommand {
            fire_left: true,
            ..Default::default()
        };
        w.tick(away(), fwd);
        assert_eq!(w.accel_override(), Some(3.0), "the cast tick channels");
        assert_eq!(
            w.player.mana_delta,
            -(cost as i32),
            "the cast stamps the debit onto the regen delta"
        );

        // The debit lands on the next wizard tick and empties the
        // pool, so this re-arm is refused: the burst keeps propelling
        // at 2.0 rather than cancelling, and the hold is over.
        w.tick(away(), fwd);
        assert_eq!(w.player.mana, 0, "the held tick actually spent the pool");
        assert_eq!(
            w.accel_override(),
            Some(2.0),
            "an unaffordable re-arm falls back to the 2.0 glide"
        );
        assert_ne!(w.player.accel, 0, "exhaustion does not cancel the channel");

        // And it stays refused while the pool is short of the FULL
        // cost — no partial-price 3.0.
        for _ in 0..4 {
            w.tick(away(), fwd);
            assert_eq!(w.accel_override(), Some(2.0), "still unaffordable");
            assert!(w.player.mana < cost, "regen has not refunded an arm yet");
        }
    }

