    /// The rival castle-rebuild POVERTY GATE (sub_13F00 :18359 →
    /// sub_15E90 :19375: `manifest16 +136 <= wizard mana_max`, with the
    /// teardown re-stamp sub_47A70 :56527-28 → sub_47C60 case 0 pricing
    /// a razed wizard's token at CAP[0] = 5000). A destroyed, starved
    /// rival must NOT rebuild until the census ceiling crosses 5000 —
    /// the mc1l5 take's Vodor experiment (castle-less at mana_max
    /// 1.7-3.8k for ~2,000 ticks, rebuilt at t=17643 the moment
    /// mana_max hit 5,322).
    #[test]
    fn rival_rebuild_waits_out_poverty_at_the_death_stamp() {
        use crate::mc1::rivals::RivalConfig;
        let mut book = [false; SPELL_COUNT];
        book[16] = true;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let mut w = World::new(planes, &rival_marker_things(), 1, assets());
        let mut cfgs: [Option<RivalConfig>; 8] = Default::default();
        cfgs[1] = Some(RivalConfig {
            aggression: 200,
            accuracy: 255,
            tempo: 255,
            castle_level: 2, // spawns housed at level 1
            book,
            allowed: book,
        });
        w.set_wizards(&cfgs, 2);
        let rid = w.rivals[0].ent;
        let pose = PlayerPose::level(200 << 8, 200 << 8, 3400, 0);
        for _ in 0..5 {
            w.tick(pose, PlayerCommand::default());
        }
        assert!(w.rival_castle(rid).is_some(), "housed by construction");
        let m = w.rivals[0].owned[16] as usize;
        assert_ne!(m, 0, "the mint registered the manifestation");
        assert_eq!(
            w.g.ent[m].f136, 1000,
            "rival token keeps the ctor seed while housed (no \
             every-tick stamp for rivals — mc1l5 t=0, Vodor 1000/9)"
        );
        // Raze it — one lethal write per tick until every level is
        // knocked down (the downgrade eats one rung per hit). The
        // death arm must re-price the token at CAP[0].
        for _ in 0..200 {
            if let Some(cc) = w.rival_castle(rid) {
                w.g.ent[cc].act_life = -1;
            } else {
                break;
            }
            w.tick(pose, PlayerCommand::default());
        }
        assert!(w.rival_castle(rid).is_none(), "the castle died");
        assert_eq!(
            w.g.ent[m].f136 as u32,
            crate::engine::features::Gen::CASTLE_CAP[0] as u32,
            "the teardown stamps the token at CAP[0] = 5000"
        );
        // Starve: strip every mana ball (the death scatter included) so
        // the census collapses to the intrinsic 1000 base.
        for _ in 0..300 {
            for j in 1..w.g.ent.len() {
                if w.g.ent[j].class64 == 10 && w.g.ent[j].model65 == 39 {
                    w.g.ent[j].flags |= 0x400;
                }
            }
            w.tick(pose, PlayerCommand::default());
            assert!(
                w.rival_castle(rid).is_none(),
                "poverty: mana_max {} < 5000 must not rebuild",
                w.rivals[0].mana_max
            );
        }
        assert_eq!(w.rivals[0].mana_max, WIZARD_BASE_MANA);
        // One fat claimed ball releases the gate (the census credits
        // f140 through the f144 claim to the rival's ceiling).
        let b = w.g.new_event().expect("pool has room");
        {
            let e = &mut w.g.ent[b];
            e.class64 = 10;
            e.model65 = 39;
            e.f140 = 5000;
            e.f144 = rid;
            e.max_life = 10000;
            e.act_life = 10000;
        }
        let mut rebuilt = false;
        for _ in 0..4000 {
            w.tick(pose, PlayerCommand::default());
            if w.rival_castle(rid).is_some() {
                rebuilt = true;
                break;
            }
        }
        assert!(rebuilt, "mana_max past the 5000 stamp rebuilds");
    }

    /// Regression: the attack-spell picker must not FREEZE on a
    /// castle-tier spell a rival owns but can't unlock (its castle stores
    /// less than the spell's castle_req). The bug folded the castle-stored
    /// gate into cast-readiness, so the picker parked forever (returned
    /// None) on the affordable-by-ceiling-but-castle-locked spell and never
    /// fell through to castle-free Fireball — the "follows the target,
    /// casts nothing" report. Retail keeps the ladder out of the picker
    /// (`sub_15A00`) and enforces it at emission (`sub_55DD0` :65049,
    /// fizzle). This exercises the picker directly, in the freeze regime a
    /// castle-less rival hits with Lightning: cost 1000 == mana_max 1000,
    /// so `mana_max >= cost` holds while the 25000 castle_req never can.
    /// Both assertions return None on the pre-fix code (non-vacuous).
    #[test]
    fn castle_gated_spell_does_not_freeze_the_picker() {
        use crate::mc1::mobs::PLAYER_TARGET;
        use crate::mc1::rivals::RivalConfig;
        // Castle-less rival (no spell 16 → no castle, mana_max stays 1000)
        // owning Fireball(0, castle-free) and Lightning(15, castle_req
        // 25000, cost 1000). acc 255 keeps the aim cone tight and makes the
        // anti-rebound insert deterministic.
        let mut book = [false; SPELL_COUNT];
        book[0] = true;
        book[15] = true;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let mut w = World::new(planes, &rival_marker_things(), 1, assets());
        let mut cfgs: [Option<RivalConfig>; 8] = Default::default();
        cfgs[1] = Some(RivalConfig {
            aggression: 200,
            accuracy: 255,
            tempo: 255,
            castle_level: 0,
            book,
            allowed: book,
        });
        w.set_wizards(&cfgs, 2);
        let rid = w.rivals[0].ent;
        assert!(w.rival_castle(rid).is_none(), "castle-less by construction");
        assert!(
            w.rivals[0].owned[0] != 0 && w.rivals[0].owned[15] != 0,
            "both spells minted"
        );

        // Aim the rival dead at a PLAYER target that is REBOUNDING, so
        // Lightning is spliced high into the pick order (before Fireball).
        w.rivals[0].target = PLAYER_TARGET;
        w.rivals[0].mana = 1000;
        w.rivals[0].mana_max = 1000;
        w.player.rebound = true;
        let (ex, ey) = (w.g.ent[rid as usize].x, w.g.ent[rid as usize].y);
        let (hx, hy) = (ex.wrapping_add(5000), ey);
        w.human_pose = (hx, hy, w.g.ent[rid as usize].z);
        w.g.ent[rid as usize].f30 = Gen::angle_between(ex, ey, hx, hy);

        // (a) Lightning is affordable-by-ceiling AND castle-locked. Pre-fix
        // readiness folded in the castle gate → not-ready → picker parks on
        // the WAIT and returns None. Post-fix it is ready (no castle term)
        // and the picker fires it (it will fizzle harmlessly at emission).
        assert_eq!(
            w.rival_attack_pick(0, true),
            Some(15),
            "castle-locked Lightning must be pickable, not a permanent WAIT"
        );

        // (b) With Lightning on its recast cooldown, the picker must FALL
        // THROUGH to castle-free Fireball. Pre-fix it returned None (no
        // cooldown escape in the WAIT branch); post-fix the escape advances.
        w.rivals[0].cooldown[15] = 1;
        assert_eq!(
            w.rival_attack_pick(0, true),
            Some(0),
            "a cooling high-priority spell must yield to Fireball, not freeze"
        );
    }

    /// The mana-hunt (`sub_14B10` :18650) targets foreign mana-carrying
    /// CREATURES only — it walks the per-model buckets 0..=19, so loose mana
    /// balls (model 39) and dwellings (model 45) are NOT hunted (that is the
    /// Possess/ball-claim path's job) — and only when the rival owns an
    /// offense spell (`sub_16920` gate :18662). The offense gate is the
    /// non-vacuous part: pre-fix an offense-less rival still entered HuntMana
    /// and shadowed the target casting nothing.
    #[test]
    fn mana_hunt_targets_creatures_only_and_needs_offense() {
        use crate::mc1::rivals::RivalConfig;
        let planes = Planes {
            height: vec![100; 0x10000],
            tile_type: vec![5; 0x10000],
            shading: vec![32; 0x10000],
            angle: vec![5; 0x10000],
            ceiling: Vec::new(),
        };
        let mut w = World::new(planes, &rival_marker_things(), 1, assets());
        let mut cfgs: [Option<RivalConfig>; 8] = Default::default();
        // Rival owns Fireball only (an offense spell).
        let mut book = [false; SPELL_COUNT];
        book[0] = true;
        cfgs[1] = Some(RivalConfig {
            aggression: 200,
            accuracy: 255,
            tempo: 255,
            castle_level: 0,
            book,
            allowed: book,
        });
        w.set_wizards(&cfgs, 2);
        let rid = w.rivals[0].ent;
        let (rx, ry) = (w.g.ent[rid as usize].x, w.g.ent[rid as usize].y);

        // A foreign mana-carrying CREATURE dead ahead.
        let mob = w.g.spawn_creature(16, rx + 4096, ry, 100).unwrap(); // wyvern
        w.g.ent[mob].id24 = 0; // wild
        w.g.ent[mob].f140 = 5000;

        // A loose mana ball (class 10 model 39) carrying mana — a NON-creature
        // holder the mana-hunt must NOT see (higher per-model bucket).
        let ball = w.g.spawn_creature(5, rx + 2048, ry, 100).unwrap();
        w.g.ent[ball].class64 = 10;
        w.g.ent[ball].model65 = 39;
        w.g.ent[ball].id24 = 0;
        w.g.ent[ball].f140 = 9000; // richer + nearer than the creature

        // (a) The creature is hunted; the nearer/richer ball is invisible.
        assert!(
            w.rival_pick_mana_target(0, rid as usize),
            "a mana creature must be huntable"
        );
        assert_eq!(
            w.rivals[0].target, mob as u16,
            "the creature is the target, not the ball"
        );

        // (b) Strip the rival's offense: the same world now yields NO hunt
        // (pre-fix it entered HuntMana and cast nothing).
        w.rivals[0].owned[0] = 0;
        assert!(!w.rival_has_offense(0), "offense stripped");
        w.rivals[0].state = crate::mc1::rivals::AiState::Fresh;
        w.rivals[0].target = 0;
        assert!(
            !w.rival_pick_mana_target(0, rid as usize),
            "an offense-less rival must not enter HuntMana"
        );
    }

    #[test]
    fn rival_death_scatters_jars_and_castleless_death_eliminates() {
        let mut w = rival_world(false, 0);
        let rid = w.rivals[0].ent as usize;
        // Kill it: a lethal ch0 hit from the player (grace spent).
        w.rivals[0].grace = 0;
        w.g.ent[rid].mail[0] = (60000, PLAYER_TARGET);
        for _ in 0..300 {
            w.tick(away(), PlayerCommand::default());
            if w.rivals[0].eliminated {
                break;
            }
        }
        assert!(w.rivals[0].eliminated, "castle-less death must eliminate");
        // The kill credited to the human.
        assert_eq!(w.player_kill_row()[1], 1);
        // The known book scattered as decaying ground jars + a grave.
        let jars =
            w.g.ent
                .iter()
                .filter(|e| e.class64 == 12 && e.tick70 == DROPPED_JAR && e.flags & 0x400 == 0)
                .count();
        assert_eq!(jars, 1, "one owned spell scatters one jar");
        assert!(
            w.g.ent
                .iter()
                .any(|e| e.class64 == 10 && e.model65 == 40 && e.flags & 0x400 == 0),
            "the grave spawned"
        );
        // Hidden husk: not in the drawable set.
        assert!(
            !w.live_poses().iter().any(|p| p.class == 3 && p.model == 1),
            "the dead wizard billboard must be hidden"
        );
        let death_slots = w.take_rival_deaths();
        assert_eq!(death_slots, vec![1]);
    }

    #[test]
    fn rival_with_castle_respawns_with_grace() {
        let mut w = rival_world(true, 1);
        let rid = w.rivals[0].ent as usize;
        w.rivals[0].grace = 0;
        w.g.ent[rid].mail[0] = (60000, PLAYER_TARGET);
        let mut respawned = false;
        for _ in 0..2000 {
            w.tick(away(), PlayerCommand::default());
            if w.g.ent[rid].tick70 == 1 && w.g.ent[rid].act_life > 0 {
                respawned = true;
                break;
            }
        }
        assert!(respawned, "the castled rival must respawn");
        assert!(!w.rivals[0].eliminated);
        // Back at the castle.
        let c = w.rival_castle(w.rivals[0].ent).unwrap();
        assert_eq!(w.g.ent[rid].x >> 8, w.g.ent[c].x >> 8);
    }

